const RequestParser = require('./requestParser');
const ResponseBuilder = require('./responseBuilder');
const XMLBuilder = require('./xmlBuilder');

class SAMLIdentityProvider {
    constructor(config) {
        this.config = config;
        this.responseBuilder = new ResponseBuilder(config);
        this.processedRequestIds = new Map();
    }

    parseAuthnRequest(samlRequest, binding = 'redirect') {
        const xml = RequestParser.decodeSAMLRequest(samlRequest, binding);
        const parsed = RequestParser.parseAuthnRequest(xml);

        if (parsed.issueInstant) {
            const timestampValidation = RequestParser.validateTimestamp(parsed.issueInstant);
            if (!timestampValidation.valid) {
                throw new Error(timestampValidation.message);
            }
        }

        return parsed;
    }

    parseLogoutRequest(samlRequest, binding = 'redirect') {
        const xml = RequestParser.decodeSAMLRequest(samlRequest, binding);
        const parsed = RequestParser.parseLogoutRequest(xml);

        if (parsed.issueInstant) {
            const timestampValidation = RequestParser.validateTimestamp(parsed.issueInstant);
            if (!timestampValidation.valid) {
                throw new Error(timestampValidation.message);
            }
        }

        return parsed;
    }

    validateRequestId(requestId, issueInstant) {
        if (!requestId) {
            return { valid: false, message: 'Missing Request ID' };
        }

        const MAX_AGE = 5 * 60 * 1000;
        const now = Date.now();

        if (issueInstant) {
            const issueTime = new Date(issueInstant).getTime();
            if (isNaN(issueTime)) {
                return { valid: false, message: 'Invalid IssueInstant' };
            }

            if (now - issueTime > MAX_AGE) {
                return { valid: false, message: 'SAML request has expired' };
            }

            if (issueTime > now + 60000) {
                return { valid: false, message: 'SAML request time is invalid' };
            }
        }

        if (this.processedRequestIds.has(requestId)) {
            return { valid: false, message: 'Duplicate SAML request (replay protection)' };
        }

        this.processedRequestIds.set(requestId, now);

        const CLEANUP_AGE = 10 * 60 * 1000;
        for (const [id, timestamp] of this.processedRequestIds.entries()) {
            if (now - timestamp > CLEANUP_AGE) {
                this.processedRequestIds.delete(id);
            }
        }

        return { valid: true };
    }

    createLoginResponse(user, options) {
        const attributes = [
            { name: 'uid', value: String(user.uid || user.id || ''), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' },
            { name: 'username', value: String(user.username || ''), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' },
            { name: 'email', value: String(user.email || ''), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' },
            { name: 'displayName', value: String(user.displayName || user.display_name || user.username || ''), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' },
            { name: 'role', value: String(user.role || 'user'), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' },
            { name: 'department', value: String(user.department || ''), nameFormat: 'urn:oasis:names:tc:SAML:2.0:attrname-format:basic' }
        ];

        const responseOptions = {
            inResponseTo: options.requestId,
            destination: options.acsUrl || options.destination,
            nameID: user.email || user.username || String(user.id || ''),
            nameIDFormat: options.nameIDFormat || 'urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified',
            attributes: attributes,
            sessionIndex: options.sessionIndex,
            audience: options.entityId || options.audience
        };

        return this.responseBuilder.buildLoginResponse(responseOptions);
    }

    createLogoutResponse(options) {
        return this.responseBuilder.buildLogoutResponse(options);
    }

    getMetadata(options) {
        return this.responseBuilder.buildMetadata(options);
    }

    static encodeResponse(xml) {
        return ResponseBuilder.encodeResponse(xml);
    }

    static decodeRequest(samlRequest, binding = 'redirect') {
        return RequestParser.decodeSAMLRequest(samlRequest, binding);
    }
}

module.exports = SAMLIdentityProvider;

const XMLBuilder = require('./xmlBuilder');
const XMLSigner = require('./xmlSigner');

class ResponseBuilder {
    constructor(config) {
        this.issuer = config.issuer;
        this.certificate = config.certificate;
        this.privateKey = config.privateKey;
        this.signer = new XMLSigner(this.privateKey, this.certificate);
    }

    buildLoginResponse(options) {
        const {
            inResponseTo,
            destination,
            nameID,
            nameIDFormat = 'urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified',
            attributes = [],
            sessionIndex,
            audience
        } = options;

        const responseID = XMLBuilder.generateID();
        const assertionID = XMLBuilder.generateID();
        const issueInstant = XMLBuilder.getCurrentTimestamp();
        const notBefore = issueInstant;
        const notOnOrAfter = XMLBuilder.getFutureTimestamp(5);
        const subjectNotOnOrAfter = XMLBuilder.getFutureTimestamp(5);
        const finalSessionIndex = sessionIndex || XMLBuilder.generateID();

        const responseWithoutAssertion = XMLBuilder.buildResponseWithoutAssertion({
            responseID,
            issueInstant,
            destination,
            issuer: this.issuer,
            inResponseTo,
            statusCode: 'urn:oasis:names:tc:SAML:2.0:status:Success'
        });

        const assertion = XMLBuilder.buildAssertion({
            assertionID,
            issueInstant,
            issuer: this.issuer,
            nameID,
            nameIDFormat,
            recipient: destination,
            audience: audience || destination,
            inResponseTo,
            sessionIndex: finalSessionIndex,
            attributes,
            notBefore,
            notOnOrAfter,
            subjectNotOnOrAfter
        });

        const signedAssertion = this.signer.signAssertion(assertion, assertionID);

        const signedResponse = this.signer.signResponse(
            responseWithoutAssertion,
            responseID,
            signedAssertion
        );

        return signedResponse;
    }

    buildLogoutResponse(options) {
        const {
            inResponseTo,
            destination,
            statusCode = 'urn:oasis:names:tc:SAML:2.0:status:Success'
        } = options;

        const responseID = XMLBuilder.generateID();
        const issueInstant = XMLBuilder.getCurrentTimestamp();

        return XMLBuilder.buildLogoutResponse({
            responseID,
            issueInstant,
            destination,
            issuer: this.issuer,
            inResponseTo,
            statusCode
        });
    }

    buildMetadata(options) {
        const {
            entityID,
            ssoLocation,
            sloLocation,
            nameIDFormats
        } = options;

        return XMLBuilder.buildMetadata({
            entityID: entityID || this.issuer,
            certificate: this.certificate,
            ssoLocation,
            sloLocation,
            nameIDFormats
        });
    }

    static encodeResponse(xml) {
        return Buffer.from(xml, 'utf8').toString('base64');
    }
}

module.exports = ResponseBuilder;

const config = require('../config/config');

const User = require('../models/User');
const { validationResult } = require('express-validator');


class AuthController {
    static showRegister(req, res) {
        res.render('register', {
            title: 'User Registration',
            errors: [],
            formData: {}
        });
    }

    static async register(req, res) {
        const errors = validationResult(req);

        if (!errors.isEmpty()) {
            return res.render('register', {
                title: 'User Registration',
                errors: errors.array(),
                formData: req.body
            });
        }

        const { username, email, password, type, invitationCode, displayName, department } = req.body;

        try {
            const existingUser = await User.findByUsername(username);
            if (existingUser) {
                return res.render('register', {
                    title: 'User Registration',
                    errors: [{ msg: 'Username already exists' }],
                    formData: req.body
                });
            }

            const existingEmail = await User.findByEmail(email);
            if (existingEmail) {
                return res.render('register', {
                    title: 'User Registration',
                    errors: [{ msg: 'Email already registered' }],
                    formData: req.body
                });
            }


            if (parseInt(type) === 0) {
                if (!invitationCode || invitationCode !== config.getInviteCode()) {
                    return res.render('register', {
                        title: 'User Registration',
                        errors: [{ msg: 'Invalid invitation code' }],
                        formData: req.body
                    });
                }

            }

            req.session.userId = await User.create({
                username,
                email,
                password,
                type,
                displayName: displayName || username,
                department,
                role: 'user'
            });
            req.session.username = username;
            req.session.userType = type;
            req.session.userRole = 'user';

            res.redirect('/portal');
        } catch (error) {
            console.error('[Auth] User registration failed:', error.message);
            console.error(error);
            res.render('register', {
                title: 'User Registration',
                errors: [{ msg: 'Registration failed, please try again later' }],
                formData: req.body
            });
        }
    }

    static showLogin(req, res) {
        const samlRequest = req.query.SAMLRequest || '';
        const relayState = req.query.RelayState || '';
        const oauth2Params = {
            clientId: req.query.client_id || '',
            redirectUri: req.query.redirect_uri || '',
            responseType: req.query.response_type || '',
            state: req.query.state || '',
            scope: req.query.scope || ''
        };

        res.render('login', {
            title: 'User Login',
            errors: [],
            formData: {},
            samlRequest,
            relayState,
            oauth2Params
        });
    }

    static async login(req, res) {
        const { username, password } = req.body;
        const samlRequest = req.body.samlRequest || '';
        const relayState = req.body.relayState || '';

        try {
            const user = await User.findByUsername(username);

            if (!user) {
                return res.render('login', {
                    title: 'User Login',
                    errors: [{ msg: 'Invalid username or password' }],
                    formData: { username },
                    samlRequest,
                    relayState,
                    oauth2Params: {}
                });
            }

            const isValidPassword = await User.verifyPassword(password, user.password);

            if (!isValidPassword) {
                return res.render('login', {
                    title: 'User Login',
                    errors: [{ msg: 'Invalid username or password' }],
                    formData: { username },
                    samlRequest,
                    relayState,
                    oauth2Params: {}
                });
            }

            await User.updateLastLogin(user.id);

            req.session.userId = user.id;
            req.session.username = user.username;
            req.session.userType = user.type;
            req.session.userRole = user.role;
            req.session.userEmail = user.email;
            req.session.displayName = user.display_name || user.username;

            if (samlRequest) {
                return res.redirect(`/saml/sso?SAMLRequest=${encodeURIComponent(samlRequest)}&RelayState=${encodeURIComponent(relayState)}`);
            }

            const oauth2ClientId = req.body.oauth2ClientId || req.query.client_id;
            if (oauth2ClientId) {
                const params = new URLSearchParams({
                    client_id: oauth2ClientId,
                    redirect_uri: req.body.oauth2RedirectUri || req.query.redirect_uri,
                    response_type: req.body.oauth2ResponseType || req.query.response_type || 'code',
                    state: req.body.oauth2State || req.query.state || '',
                    scope: req.body.oauth2Scope || req.query.scope || 'profile'
                });
                return res.redirect(`/oauth/authorize?${params.toString()}`);
            }

            res.redirect('/portal');
        } catch (error) {
            console.error('[Auth] User login failed:', error.message);
            console.error(error);
            res.render('login', {
                title: 'User Login',
                errors: [{ msg: 'Login failed, please try again later' }],
                formData: { username },
                samlRequest,
                relayState,
                oauth2Params: {}
            });
        }
    }

    static async logout(req, res) {
        req.session.destroy((err) => {
            if (err) {
                console.error('[Auth] Session destroy failed:', err.message);
            }
            res.redirect('/');
        });
    }

    static async getCurrentUser(req, res) {
        try {
            const user = await User.findById(req.session.userId);

            if (!user) {
                return res.status(404).json({ error: 'User does not exist' });
            }

            res.json({
                success: true,
                data: User.sanitizeUser(user)
            });
        } catch (error) {
            console.error('[Auth] Get current user failed:', error.message);
            console.error(error);
            res.status(500).json({ error: 'Server error' });
        }
    }
}

module.exports = AuthController;

const fs = require('fs');
const path = require('path');
const yaml = require('yamljs');
const crypto = require('crypto');

const CONFIG_PATH = path.join(__dirname,  '../../config.yml');
let config = null;

try {
    if (!fs.existsSync(CONFIG_PATH)) {
        throw new Error(`Configuration file does not exist: ${CONFIG_PATH}`);
    }

    config = yaml.load(CONFIG_PATH);

    config.session.secret = crypto.randomBytes(32).toString('hex');
    config.server.invitationCode = crypto.randomBytes(16).toString('hex');


    if (process.env.NODE_ENV) {
        config.server.env = process.env.NODE_ENV;
    }

    if (process.env.PORT) {
        config.server.port = parseInt(process.env.PORT, 10);
    }

    if (process.env.CERT_PATH) {
        config.server.certPath = process.env.CERT_PATH;
    }

    if (process.env.PRIVATE_KEY_PATH) {
        config.server.privateKeyPath = process.env.PRIVATE_KEY_PATH;
    }

    if (process.env.DB_HOST) {
        config.database.host = process.env.DB_HOST;
    }

    if (process.env.DB_PORT) {
        config.database.port = parseInt(process.env.DB_PORT, 10);
    }

    if (process.env.DB_USER) {
        config.database.user = process.env.DB_USER;
    }

    if (process.env.DB_PASSWORD) {
        config.database.password = process.env.DB_PASSWORD;
    }

    if (process.env.DB_NAME) {
        config.database.database = process.env.DB_NAME;
    }


    if (process.env.SAML_ISSUER) {
        config.saml.issuer = process.env.SAML_ISSUER;
    }

} catch (error) {
    console.error(error);
    process.exit(1);
}

function getServerConfig() {
    return config.server;
}

function getDatabaseConfig() {
    return config.database;
}

function getSessionConfig() {
    return config.session;
}

function getSamlConfig() {
    return config.saml;
}

function getServicesConfig() {
    return config.services || [];
}

function getLoggingConfig() {
    return config.logging;
}

function getSecurityConfig() {
    return config.security;
}

function getInviteCode() {
    return config.server.invitationCode;
}

function isProduction() {
    return config.server.env === 'production';
}

function getCertPath() {
    return path.join(__dirname, '../..', config.server.certPath);
}

function getPrivateKeyPath() {
    return path.join(__dirname, '../..', config.server.privateKeyPath);
}


function getCertificate() {
    const certPath = getCertPath();
    if (!fs.existsSync(certPath)) {
        throw new Error(`Certificate file does not exist: ${certPath}`);
    }
    return fs.readFileSync(certPath, 'utf8');
}

function getPrivateKey() {
    const keyPath = getPrivateKeyPath();
    if (!fs.existsSync(keyPath)) {
        throw new Error(`Private key file does not exist: ${keyPath}`);
    }
    return fs.readFileSync(keyPath, 'utf8');
}

module.exports = {
    getServerConfig,
    getDatabaseConfig,
    getSessionConfig,
    getSamlConfig,
    getServicesConfig,
    getLoggingConfig,
    getSecurityConfig,
    getInviteCode,
    isProduction,
    getCertificate,
    getPrivateKey
};

from flask import Flask, request, render_template, session, redirect, url_for, render_template_string
import os

from saml2 import SAMLResponseParser, AuthnRequestBuilder
from config import saml_config

app = Flask(__name__)
app.secret_key = os.urandom(24)

SP_ENTITY_ID = saml_config.sp_entity_id
SP_ACS_URL = saml_config.sp_acs_url
IDP_SSO_URL = saml_config.idp_sso_url
IDP_CERT = saml_config.get_idp_cert()

processed_assertion_ids = set()


@app.route('/')
def index():
    if 'email' in session:
        return redirect(url_for('admin'))
    return render_template('index.html', config=saml_config)


@app.route('/saml/login')
def saml_login():
    relay_state = request.args.get('next', '/')

    builder = AuthnRequestBuilder(
        sp_entity_id=SP_ENTITY_ID,
        acs_url=SP_ACS_URL,
        idp_sso_url=IDP_SSO_URL
    )

    redirect_url = builder.get_redirect_url(relay_state=relay_state)

    return redirect(redirect_url)


@app.route('/saml/acs', methods=['POST'])
def saml_acs():
    try:
        saml_response = request.form.get('SAMLResponse')
        relay_state = request.form.get('RelayState', '/admin')

        if not saml_response:
            return render_template('error.html', error='No SAML response received'), 400

        parser = SAMLResponseParser(
            saml_response, 
            IDP_CERT,
            validate_time=saml_config.validate_time,
            validate_audience=saml_config.validate_audience,
            expected_audience=SP_ENTITY_ID,
            validate_destination=saml_config.validate_destination,
            expected_destination=SP_ACS_URL,
            time_tolerance=saml_config.time_tolerance
        )

        if not parser.is_valid():
            return render_template('error.html', error='SAML response validation failed'), 401

        assertion_ids = parser.get_assertion_ids()
        for assertion_id in assertion_ids:
            if assertion_id in processed_assertion_ids:
                return render_template('error.html', error='Replay attack detected'), 401
            processed_assertion_ids.add(assertion_id)

        nameid = parser.get_nameid()

        if not nameid:
            return render_template('error.html', error='Unable to get user identifier'), 401

        session['email'] = nameid

        return redirect(url_for('admin'))

    except Exception as e:
        return render_template('error.html', error=f'Error processing SAML response: {str(e)}'), 500


@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('index'))


@app.route('/admin')
def admin():
    if 'email' not in session:
        return redirect(url_for('saml_login'))

    if session.get('email') != 'admin@rois.team':
        return render_template('error.html', error='Insufficient permissions, admin access only'), 403

    return render_template_string(os.getenv("FLAG","RCTF{test_flag}"))


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=26000, debug=False)

